import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model of the CLEVRER physics simulation.

    Objects slide on a flat floor with friction, collide elastically,
    and enter/exit the scene at specific frames.
    """

    end_time = recorded_end(doc, scope)

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = end_time

    if horizon is None:
        horizon = 127.0

    # Get entry information from document (position/velocity when objects first appear)
    entry_info = _get_entry_info(doc, scope)

    # Get scene boundary from document (estimate from motion logs)
    boundary = _get_boundary(doc, scope)

    # Initialize object states and collision schedule
    states = {}  # obj_id -> {x, y, vx, vy, entered, exited}
    collisions = {}  # frame -> [(obj1, obj2)]
    entry_events = {}  # obj_id -> frame

    for inp in inputs:
        time = inp['time']
        entities = inp['entities']

        if inp['kind'] == 'initial_state':
            obj_id = entities[0]
            fields = inp['fields']
            states[obj_id] = {
                'x': fields.get('x', 0.0),
                'y': fields.get('y', 0.0),
                'vx': fields.get('vx', 0.0),
                'vy': fields.get('vy', 0.0),
                'entered': 0.0,
                'exited': None
            }
        elif inp['kind'] == 'initial_presence':
            # Object is present at frame 0 but may not have state data
            obj_id = entities[0]
            if obj_id not in states:
                states[obj_id] = {
                    'x': 0.0, 'y': 0.0,
                    'vx': 0.0, 'vy': 0.0,
                    'entered': 0.0,
                    'exited': None
                }
        elif inp['kind'] == 'enter':
            obj_id = entities[0]
            entry_events[obj_id] = time
        elif inp['kind'] == 'collision':
            frame = time
            if frame not in collisions:
                collisions[frame] = []
            collisions[frame].append((entities[0], entities[1]))

    # Handle entry events - initialize objects that enter later
    for obj_id, entry_frame in entry_events.items():
        if obj_id not in states:
            info = entry_info.get(obj_id, {})
            states[obj_id] = {
                'x': info.get('x', 0.0),
                'y': info.get('y', 0.0),
                'vx': info.get('vx', 0.0),
                'vy': info.get('vy', 0.0),
                'entered': entry_frame,
                'exited': None
            }

    # Friction coefficient (deceleration per frame)
    FRICTION = 0.01
    SPEED_THRESHOLD = 0.1
    COEFF_RESTITUTION = 0.95

    def apply_friction(state):
        vx, vy = state['vx'], state['vy']
        speed = math.sqrt(vx*vx + vy*vy)
        if speed > SPEED_THRESHOLD:
            decel = FRICTION
            new_speed = max(0, speed - decel)
            if new_speed < SPEED_THRESHOLD:
                state['vx'] = 0.0
                state['vy'] = 0.0
            else:
                state['vx'] = vx * new_speed / speed
                state['vy'] = vy * new_speed / speed

    def handle_collision(state1, state2, restitution=1.0):
        dx = state1['x'] - state2['x']
        dy = state1['y'] - state2['y']
        dist = math.sqrt(dx*dx + dy*dy)

        if dist < 0.001:
            # Objects at same position, use a small default normal
            nx, ny = 1.0, 0.0
        else:
            nx, ny = dx/dist, dy/dist

        v1x, v1y = state1['vx'], state1['vy']
        v2x, v2y = state2['vx'], state2['vy']

        # Relative velocity along collision normal
        rel_v = (v1x - v2x)*nx + (v1y - v2y)*ny

        if rel_v > 0:
            return  # Objects moving apart

        # Elastic collision response (equal mass)
        impulse = rel_v * (1 + restitution) / 2

        state1['vx'] -= impulse * nx
        state1['vy'] -= impulse * ny
        state2['vx'] += impulse * nx
        state2['vy'] += impulse * ny

    def is_in_scene(state, boundary):
        x, y = state['x'], state['y']
        return (boundary[0] <= x <= boundary[1] and 
                boundary[2] <= y <= boundary[3])

    # Collect frames where we need to record outcomes
    # We'll record motion at every frame after start
    outcomes = []
    exited_objects = set()

    # Current time
    current_time = start

    while current_time <= horizon:
        frame = int(current_time)

        # Check for collisions at this frame
        if frame in collisions:
            for obj1, obj2 in collisions[frame]:
                if obj1 in states and obj2 in states:
                    if states[obj1]['exited'] is None and states[obj2]['exited'] is None:
                        if (current_time >= states[obj1]['entered'] and 
                            current_time >= states[obj2]['entered']):
                            handle_collision(states[obj1], states[obj2], COEFF_RESTITUTION)
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": [obj1, obj2],
                                "value": None,
                                "src": []
                            })

        # Apply friction and update positions
        for obj_id in states:
            state = states[obj_id]
            if state['exited'] is not None:
                continue
            if current_time < state['entered']:
                continue

            apply_friction(state)

            # Update position
            state['x'] += state['vx']
            state['y'] += state['vy']

            # Check for exit
            if not is_in_scene(state, boundary) and current_time > state['entered']:
                if state['exited'] is None:
                    state['exited'] = float(frame)
                    outcomes.append({
                        "time": float(frame),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

        # Record motion outcomes for visible objects
        for obj_id in states:
            state = states[obj_id]
            if state['exited'] is not None:
                continue
            if current_time < state['entered']:
                continue

            # Only record motion after start
            if frame > start:
                outcomes.append({
                    "time": float(frame),
                    "kind": "motion",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

        current_time += 1.0

    return outcomes


def _get_entry_info(doc, scope):
    """Get entry position and velocity for objects from document."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    children_nodes = children(doc, scope_node)
    motion_node = None
    for child in children_nodes:
        if child['title'].endswith(': Motion log'):
            motion_node = child
            break

    if not motion_node:
        return {}

    rows = table_rows(motion_node)
    entry_info = {}

    for r_idx, row in rows:
        obj_str = row.get('object', '')
        parts = obj_str.split()
        if parts:
            obj_id = parts[0]
            if obj_id not in entry_info:
                try:
                    entry_info[obj_id] = {
                        'frame': int(row['frame']),
                        'x': float(row['x']),
                        'y': float(row['y']),
                        'vx': float(row['vx']),
                        'vy': float(row['vy'])
                    }
                except (ValueError, KeyError):
                    pass

    return entry_info


def _get_boundary(doc, scope):
    """Estimate scene boundary from motion logs."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return (-5.0, 5.0, -5.0, 5.0)

    children_nodes = children(doc, scope_node)
    motion_node = None
    for child in children_nodes:
        if child['title'].endswith(': Motion log'):
            motion_node = child
            break

    if not motion_node:
        return (-5.0, 5.0, -5.0, 5.0)

    rows = table_rows(motion_node)
    x_min, x_max = float('inf'), float('-inf')
    y_min, y_max = float('inf'), float('-inf')

    for r_idx, row in rows:
        try:
            x = float(row['x'])
            y = float(row['y'])
            x_min = min(x_min, x)
            x_max = max(x_max, x)
            y_min = min(y_min, y)
            y_max = max(y_max, y)
        except (ValueError, KeyError):
            pass

    # Add some margin for objects leaving the scene
    margin = 1.0
    return (x_min - margin, x_max + margin, y_min - margin, y_max + margin)

import re

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    children_nodes = children(doc, scope_node)

    objects_node = None
    for child in children_nodes:
        if child['title'].endswith(': Objects'):
            objects_node = child
            break

    if not objects_node or objects_node['kind'] != 'list':
        return []

    result = []
    lines = objects_node['lines']
    for line in lines:
        match = re.match(r"Object (\d+): (.+)", line)
        if match:
            obj_id = f"Object {match.group(1)}"
            desc = match.group(2)
            result.append({"id": obj_id, "description": desc})
    return result

def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    children_nodes = children(doc, scope_node)

    max_frame = -1

    motion_node = None
    events_node = None

    for child in children_nodes:
        if child['title'].endswith(': Motion log'):
            motion_node = child
        elif child['title'].endswith(': Events'):
            events_node = child

    if motion_node:
        rows = table_rows(motion_node)
        for row_idx, row in rows:
            try:
                frame = int(row['frame'])
                if frame > max_frame:
                    max_frame = frame
            except (ValueError, KeyError):
                pass

    if events_node:
        lines = events_node['lines']
        for line in lines:
            match = re.match(r"Frame (\d+):", line)
            if match:
                frame = int(match.group(1))
                if frame > max_frame:
                    max_frame = frame

    return float(max_frame) if max_frame >= 0 else None

def inputs(doc, scope):
    inputs_list = []
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    children_nodes = children(doc, scope_node)

    motion_node = None
    events_node = None

    for child in children_nodes:
        if child['title'].endswith(': Motion log'):
            motion_node = child
        elif child['title'].endswith(': Events'):
            events_node = child

    # Initial States (Frame 0) from Motion log
    if motion_node:
        rows = table_rows(motion_node)
        for row_idx, row in rows:
            try:
                frame = int(row['frame'])
            except (ValueError, KeyError):
                continue
            if frame == 0:
                obj_str = row.get('object', '')
                parts = obj_str.split()
                if not parts:
                    continue
                obj_id = f"Object {parts[0]}"

                fields = {}
                for col in ['x', 'y', 'vx', 'vy', 'speed']:
                    val_str = row.get(col, '')
                    try:
                        fields[col] = float(val_str)
                    except ValueError:
                        pass

                inputs_list.append({
                    "id": f"initial_{obj_id}",
                    "time": 0.0,
                    "kind": "initial_state",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": [[motion_node['node_id'], row_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']]]
                })

    # Enters / In view from Events
    if events_node:
        lines = events_node['lines']
        for line_idx, line in enumerate(lines):
            match = re.match(r"Frame (\d+): (Object \d+) \((.+?)\) (enters the scene|is in view when the video begins)", line)
            if match:
                frame = int(match.group(1))
                obj_id = match.group(2)
                kind = "enter" if "enters" in match.group(4) else "initial_presence"
                inputs_list.append({
                    "id": f"{kind}_{obj_id}_{frame}",
                    "time": float(frame),
                    "kind": kind,
                    "entities": [obj_id],
                    "fields": {},
                    "src": [[events_node['node_id'], line_idx]]
                })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    children_nodes = children(doc, scope_node)

    motion_node = None
    events_node = None

    for child in children_nodes:
        if child['title'].endswith(': Motion log'):
            motion_node = child
        elif child['title'].endswith(': Events'):
            events_node = child

    # Motion states (Frame > 0)
    if motion_node:
        rows = table_rows(motion_node)
        for row_idx, row in rows:
            try:
                frame = int(row['frame'])
            except (ValueError, KeyError):
                continue
            if frame > 0:
                obj_str = row.get('object', '')
                parts = obj_str.split()
                if not parts:
                    continue
                obj_id = f"Object {parts[0]}"

                outcomes_list.append({
                    "time": float(frame),
                    "kind": "motion",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[motion_node['node_id'], row_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']]]
                })

    # Events
    if events_node:
        lines = events_node['lines']
        for line_idx, line in enumerate(lines):
            # Collision
            match = re.match(r"Frame (\d+): (Object \d+) \((.+?)\) collides with (Object \d+) \((.+?)\)", line)
            if match:
                frame = int(match.group(1))
                obj1 = match.group(2)
                obj2 = match.group(4)
                outcomes_list.append({
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [obj1, obj2],
                    "value": None,
                    "src": [[events_node['node_id'], line_idx]]
                })
                continue

            # Exit
            match = re.match(r"Frame (\d+): (Object \d+) \((.+?)\) exits the scene", line)
            if match:
                frame = int(match.group(1))
                obj_id = match.group(2)
                outcomes_list.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[events_node['node_id'], line_idx]]
                })

    return outcomes_list

